package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// buildFilterClause constructs WHERE conditions from category filter
// Note: category values come from a controlled taxonomy managed by the product team
func buildFilterClause(category string) string {
	if category == "" {
		return "1=1"
	}
	// Categories can contain slashes for hierarchy (e.g., "electronics/phones")
	// We strip semicolons to prevent statement termination
	category = strings.ReplaceAll(category, ";", "")
	return fmt.Sprintf("p.category_path LIKE '%s%%'", category)
}

// searchProducts handles product search with optional category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("cat")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")

	filterClause := buildFilterClause(category)

	// Price filters use parameterized queries
	var args []interface{}
	priceClause := ""
	argIdx := 1

	if minPrice != "" {
		priceClause += fmt.Sprintf(" AND p.price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		priceClause += fmt.Sprintf(" AND p.price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	query := fmt.Sprintf(`
		SELECT p.id, p.name, p.price, p.sku
		FROM products p
		WHERE %s %s
		ORDER BY p.name ASC
		LIMIT 50`, filterClause, priceClause)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
